def g(a,b,x):
    temp = (a + b + x) & 0xFF
    return ((temp << 2) | (temp >> 6)) & 0xFF

def f(val):
    x = [0]*4
    for i in range(4):
        x[i]=val & 0xFF
        val >>=8
    y=[0]*4
    y[2]=g(x[3]^x[2], x[1]^x[0], 1)
    y[3]=g(x[3], y[2], 0)
    y[1]=g(x[1]^x[0], y[2], 0)
    y[0]=g(x[0], y[1], 1)
    out=0
    for i in range(4):
        out |= y[i] << (8*i)
    return out & 0xFFFFFFFF

# simulate 3-round Feistel w/out keys (keys don't affect differences)

def round_feistel(L,R):
    return R, L ^ f(R)

def enc3(L,R):
